customCss:
/* waylight theme: amber */
:root:root,
:root:root[data-theme] {
  --color-accent: #f2b441;
  --color-accent-contrast: #1a1206;
  --color-accent-text: #9c5d00;
  --color-bg: #fff3d6;
  --color-border: #ead9ae;
  --color-danger: #b3261e;
  --color-success: #1f7a45;
  --color-surface: #fffbf0;
  --color-surface-2: #fdf0cf;
  --color-text: #1b2238;
  --color-text-muted: #6b5f45;
  --color-warning: #8a5a00;
  --font-display: 'Fraunces Variable', Fraunces, Georgia, serif;
  --font-sans: 'Figtree Variable', Figtree, system-ui, sans-serif;
  --glow: none;
  --radius: 14px;
  --radius-small: 10px;
  --shadow: 0 1px 2px #1b22381a;
}
:root:root[data-theme='dark'] {
  --color-accent-text: #f2b441;
  --color-bg: #131829;
  --color-border: #2e3650;
  --color-danger: #ff8a80;
  --color-success: #8fd6a8;
  --color-surface: #1b2238;
  --color-surface-2: #222a44;
  --color-text: #f2efe8;
  --color-text-muted: #a7aebb;
  --color-warning: #f5c04e;
  --glow: 0 0 80px #f2b4412e;
  --shadow: 0 1px 2px #00000040;
}
